resolverParametrosComunidadAutonoma2020 = (
  comunidadAutonoma: ComunidadAutonoma
): ParametrosComunidadAutonoma => {
  const minimosAutonomicos =
    obtenerMinimosAutonomicosIrpf2020(comunidadAutonoma)

  return {
    _tag: "ParametrosComunidadAutonoma",
    comunidadAutonoma,
    anio: 2020,
    minimoAutonomicoIgualEstatal: minimosAutonomicos === MINIMOS_ESTATALES_2020,
    escalaAutonomicaIgualEstatal: comunidadAutonoma === "simulada-estatal",
    escalaEstatalGeneral: TRAMOS_IRPF_ESTATAL_GENERAL_2020,
    escalaAutonomica: obtenerEscalaAutonomicaIrpf2020(comunidadAutonoma),
    minimosAutonomicos,
    deduccionesAutonomicasSoportadas: [],
  }
}

obtenerParametrosComunidadAutonoma = ({
  anio,
  baseLiquidableGeneral,
  comunidadAutonoma,
  fechaFallecimiento,
}: EntradaParametrosComunidadAutonoma): ResultadoParametrosComunidadAutonoma =>
  Match.value(anio).pipe(
    Match.when(2012, () =>
      resolverParametrosComunidadAutonoma2012(comunidadAutonoma)
    ),
    Match.when(2013, () =>
      resolverParametrosComunidadAutonoma2013(comunidadAutonoma)
    ),
    Match.when(2014, () =>
      resolverParametrosComunidadAutonoma2014({
        baseLiquidableGeneral,
        comunidadAutonoma,
      })
    ),
    Match.when(2015, () =>
      resolverParametrosComunidadAutonoma2015({
        baseLiquidableGeneral,
        comunidadAutonoma,
        fechaFallecimiento,
      })
    ),
    Match.when(2016, () =>
      resolverParametrosComunidadAutonoma2016(comunidadAutonoma)
    ),
    Match.when(2017, () =>
      resolverParametrosComunidadAutonoma2017(comunidadAutonoma)
    ),
    Match.when(2018, () =>
      resolverParametrosComunidadAutonoma2018(comunidadAutonoma)
    ),
    Match.when(2019, () =>
      resolverParametrosComunidadAutonoma2019(comunidadAutonoma)
    ),
    Match.when(2020, () =>
      resolverParametrosComunidadAutonoma2020(comunidadAutonoma)
    ),
    Match.when(2021, () =>
      resolverParametrosComunidadAutonoma2021(comunidadAutonoma)
    ),
    Match.when(2022, () =>
      resolverParametrosComunidadAutonoma2022({
        comunidadAutonoma,
        fechaFallecimiento,
      })
    ),
    Match.when(2023, () =>
      resolverParametrosComunidadAutonoma2023({
        comunidadAutonoma,
        fechaFallecimiento,
      })
    ),
    Match.when(2024, () =>
      resolverParametrosComunidadAutonoma2024(comunidadAutonoma)
    ),
    Match.when(2025, () =>
      resolverParametrosComunidadAutonoma2025(comunidadAutonoma)
    ),
    Match.when(2026, () =>
      resolverParametrosComunidadAutonoma2026(comunidadAutonoma)
    ),
    Match.orElse(
      (anio) =>
        ({
          _tag: "ComunidadAutonomaNoSoportada",
          comunidadAutonoma,
          anio,
          motivo: `Escalas autonomicas del anio ${anio} aun no implementadas`,
          fuenteReconocida:
            "https://sede.agenciatributaria.gob.es/Sede/ayuda/manuales-videos-folletos/manuales-ayuda-presentacion/irpf-2025/8-cumplimentacion-irpf/8_4-cuota-integra/8_4_3-gravamen-base-liquidable-general/8_4_3_2-cuota-integra-autonomica.html",
        }) satisfies ComunidadAutonomaNoSoportada
    )
  )

calcularDesgloseCuotaPorEscala = ({
  base,
  tramos,
  escalasPublicadas,
}: {
  readonly base: Decimal
  readonly tramos: TramosIrpf
  readonly escalasPublicadas?: ReadonlyArray<EscalaPublicada> | undefined
}): ReadonlyArray<TramoCuotaCalculado> =>
  escalasPublicadas !== undefined
    ? EffectArray.flatMap(escalasPublicadas, (filas) =>
        Option.match(
          EffectArray.findLast(
            filas,
            (fila) =>
              base.gt(0) &&
              (fila.inferiorExclusivo === true
                ? base.gt(fila.baseInferior)
                : base.gte(fila.baseInferior))
          ),
          {
            onNone: () => [],
            onSome: (fila) => [
              {
                limiteInferior: fila.baseInferior,
                limiteSuperior: Option.match(
                  EffectArray.findFirst(filas, (otra) =>
                    otra.baseInferior.gt(fila.baseInferior)
                  ),
                  {
                    onNone: () => new Decimal(Infinity),
                    onSome: (otra) => otra.baseInferior,
                  }
                ),
                baseAplicada: base.minus(fila.baseInferior),
                tipo: fila.tipo,
                cuotaFija: fila.cuota,
                cuota: fila.cuota.plus(
                  base.minus(fila.baseInferior).mul(fila.tipo)
                ),
              },
            ],
          }
        )
      )
    : Match.value(base).pipe(
        Match.when(
          (base) => base.lte(0),
          () => []
        ),
        Match.orElse(
          (base) =>
            EffectArray.reduce(
              tramos,
              {
                limiteAnterior: base.mul(0),
                tramos: EffectArray.empty<TramoCuotaGeneralCalculado>(),
              },
              (estado, [limite, tipo]) => {
                const baseRestante = Decimal.max(
                  0,
                  base.minus(estado.limiteAnterior)
                )
                const anchoTramo = limite.minus(estado.limiteAnterior)
                const importeEnTramo = Decimal.min(baseRestante, anchoTramo)
                const tramo = {
                  limiteInferior: estado.limiteAnterior,
                  limiteSuperior: limite,
                  baseAplicada: importeEnTramo,
                  tipo,
                  cuota: importeEnTramo.mul(tipo),
                }

                return {
                  limiteAnterior: limite,
                  tramos: Match.value(importeEnTramo).pipe(
                    Match.when(
                      (importeEnTramo) => importeEnTramo.gt(0),
                      () => [...estado.tramos, tramo]
                    ),
                    Match.orElse(() => estado.tramos)
                  ),
                }
              }
            ).tramos
        )
      )
